# Compute count of column 'Date' grouped by 'Venue'
print(f"🔧 Computing count of 'Date' grouped by 'Venue'")

# Check if columns exist and operation is valid
if 'Date' not in df.columns:
    print(f"❌ Error: Column 'Date' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif 'Venue' not in df.columns:
    print(f"❌ Error: Group by column 'Venue' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif "count" not in ['count', 'sum', 'avg', 'min', 'max']:
    print(f"❌ Error: Invalid operation 'count'. Valid operations: ['count', 'sum', 'avg', 'min', 'max']")
else:
    try:
        if "count" == "count":
            result = df.groupby('Venue')['Date'].count()
        elif "count" == "sum":
            result = df.groupby('Venue')['Date'].sum()
        elif "count" == "avg":
            result = df.groupby('Venue')['Date'].mean()
        elif "count" == "min":
            result = df.groupby('Venue')['Date'].min()
        elif "count" == "max":
            result = df.groupby('Venue')['Date'].max()

        print(f"✅ Count of 'Date' by 'Venue':")
        print(result)

        # Convert to dataframe for consistency
        result_df = result.reset_index()
        result_df.columns = ['Venue', f'count_result']
        print(f"\n🔍 Result as table:")
        print(result_df)

    except Exception as e:
        print(f"❌ Error computing grouped count: {e}")
        print(f"Column dtypes: {df[['Date', 'Venue']].dtypes}")
